// Silbentrennung: hyphenation points of words with Liang's algorithm on LibreOffice's Hyphen
// patterns (hyph/*.ts, generated by tools/lang-data/build.py, D-050). German has two levels as
// in Hyphen's NEXTLEVEL: the first finds the boundaries of compounds (Wach|stube), the second
// the syllables of each part, each part keeping the compound minimum (two letters) at a
// boundary and the word's minimum at its ends. Patterns are loaded on first use; until then
// a language has no hyphenation and `onHyphenationReady` tells the layout to try again.

interface PatternData { left: number; right: number; compoundLeft: number; compoundRight: number; compound: string; patterns: string }

class Patterns {
  private readonly map = new Map<string, Uint8Array>();
  private maxLen = 0;

  constructor(list: string) {
    for (const pat of list.split(" ")) {
      if (!pat) continue;
      let letters = "";
      const vals: number[] = [0];
      for (const ch of pat) {
        if (ch >= "0" && ch <= "9") vals[vals.length - 1] = Number(ch);
        else { letters += ch; vals.push(0); }
      }
      this.map.set(letters, Uint8Array.from(vals));
      this.maxLen = Math.max(this.maxLen, letters.length);
    }
  }

  get empty(): boolean {
    return this.map.size === 0;
  }

  /** Liang's values between the letters of `word` (index i: before word[i]). */
  values(word: string): Uint8Array {
    const w = `.${word}.`;
    const out = new Uint8Array(w.length + 1);
    for (let i = 0; i < w.length; i++) {
      for (let j = i + 1; j <= Math.min(w.length, i + this.maxLen); j++) {
        const v = this.map.get(w.slice(i, j));
        if (!v) continue;
        for (let k = 0; k < v.length; k++) if (v[k] > out[i + k]) out[i + k] = v[k];
      }
    }
    // Back to the word's own positions: value before word[i] is out[i + 1].
    return out.subarray(1, word.length + 2);
  }
}

export class Hyphenator {
  private readonly compound: Patterns;
  private readonly syllables: Patterns;
  private readonly cache = new Map<string, readonly number[]>();

  /** The fewest letters Word leaves before and after a hyphen at a line end. */
  readonly minLeft: number;
  readonly minRight: number;

  constructor(private readonly data: PatternData, minima?: readonly [number, number]) {
    this.compound = new Patterns(data.compound);
    this.syllables = new Patterns(data.patterns);
    this.minLeft = Math.max(data.left, minima?.[0] ?? 0);
    this.minRight = Math.max(data.right, minima?.[1] ?? 0);
  }

  /**
   * The places a word may be divided: offsets into the word after which a hyphen can stand
   * ("Silbentrennung" → [5, 9]). Only letters are hyphenated; the word is taken in lower case.
   */
  hyphenate(word: string, minLeft = this.minLeft, minRight = this.minRight): readonly number[] {
    const key = `${word}\u0001${minLeft}\u0001${minRight}`;
    const hit = this.cache.get(key);
    if (hit) return hit;
    const w = word.toLocaleLowerCase();
    const n = w.length;
    const out = new Set<number>();
    const left = Math.max(1, minLeft), right = Math.max(1, minRight);
    // Level 1: compound boundaries.
    const bounds: number[] = [];
    if (!this.compound.empty) {
      const v = this.compound.values(w);
      // Every part keeps the compound minimum (Pflanzen|t|eile has a one-letter part: only the first boundary counts).
      const minPart = Math.max(1, Math.min(this.data.compoundLeft, this.data.compoundRight));
      for (let i = 1; i < n; i++) {
        if (v[i] % 2 !== 1 || i < left || n - i < right) continue;
        if (i - (bounds[bounds.length - 1] ?? 0) < minPart || n - i < minPart) continue;
        bounds.push(i);
      }
    }
    // Level 2: the syllables of each part.
    const cuts = [0, ...bounds, n];
    for (let k = 0; k + 1 < cuts.length; k++) {
      const a = cuts[k], b = cuts[k + 1];
      const part = w.slice(a, b);
      const v = this.syllables.values(part);
      const l = a === 0 ? left : Math.max(1, this.data.compoundLeft);
      const r = b === n ? right : Math.max(1, this.data.compoundRight);
      for (let i = 1; i < part.length; i++) {
        if (v[i] % 2 === 1 && i >= l && part.length - i >= r && a + i >= left && n - a - i >= right) out.add(a + i);
      }
    }
    for (const b of bounds) out.add(b);
    const list = [...out].sort((x, y) => x - y);
    this.cache.set(key, list);
    return list;
  }
}

// ----- the languages ------------------------------------------------------------------------------

const LOADERS: Record<string, () => Promise<{ default: PatternData }>> = {
  de: () => import("./hyph/de"),
  "en-us": () => import("./hyph/en-us"),
  "en-gb": () => import("./hyph/en-gb"),
  fr: () => import("./hyph/fr"),
  es: () => import("./hyph/es"),
};

/** The pattern set for a language tag (de-AT → de, en-AU → en-gb, en-* → en-us). */
export function hyphenationKey(lang: string | undefined): string | null {
  const l = (lang ?? "").toLowerCase();
  if (l.startsWith("de")) return "de";
  if (["en-gb", "en-au", "en-nz", "en-ie", "en-za", "en-in"].includes(l)) return "en-gb";
  if (l.startsWith("en")) return "en-us";
  if (l.startsWith("fr")) return "fr";
  if (l.startsWith("es")) return "es";
  return null;
}

/**
 * Word's minimum part lengths at a line end, measured (word-hyphen-long.docx, 2026-10-14):
 * German leaves at least three letters on the next line ("Inhaltsan-gabe", "seine" whole).
 */
const MINIMA: Record<string, readonly [number, number]> = { de: [2, 3], "en-us": [2, 3], "en-gb": [2, 3], fr: [2, 3], es: [2, 2] };

const ready = new Map<string, Hyphenator>();
const loading = new Set<string>();
const listeners = new Set<() => void>();

/** Called once a language's patterns have loaded (the layout runs again). */
export function onHyphenationReady(fn: () => void): () => void {
  listeners.add(fn);
  return () => listeners.delete(fn);
}

/** The hyphenator of a language, or null while it loads (or when there is none). */
export function hyphenatorFor(lang: string | undefined): Hyphenator | null {
  const key = hyphenationKey(lang);
  if (!key) return null;
  const h = ready.get(key);
  if (h) return h;
  if (!loading.has(key)) {
    loading.add(key);
    void LOADERS[key]().then((m) => {
      ready.set(key, new Hyphenator(m.default, MINIMA[key]));
      for (const fn of listeners) fn();
    }).catch(() => { /* no hyphenation for this language */ });
  }
  return null;
}

/** Loads a language's patterns now (tests, and before measuring). */
export async function loadHyphenation(lang: string): Promise<Hyphenator | null> {
  const key = hyphenationKey(lang);
  if (!key) return null;
  if (!ready.has(key)) ready.set(key, new Hyphenator((await LOADERS[key]()).default, MINIMA[key]));
  return ready.get(key)!;
}
